public static class TutorialManualRunner {
 public static void Run(){SessionState.SetBool("TutorialManual",true);SessionState.SetString("TutorialManualDir",Path.Combine(Path.GetTempPath(),"DespachoManual-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(SessionState.GetBool("TutorialManual",false))DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=SessionState.GetString("TutorialManualDir","");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("TutorialManual",false))return;SessionState.SetBool("TutorialManual",false);new GameObject("TutorialManualProbe").AddComponent<TutorialManualProbe>();}
